+        <Link href="/cockpit/jarvis/briefing" className="hover:text-slate-400">
+          Morning briefing
+        </Link>
+        <span>›</span>
+        <span className="text-slate-400">Conversation</span>
+      </div>
+
+      {/* Conversation component — all interaction is client-side */}
+      <JarvisConversation
+        initialSummary={summary}
+        osState={osState}
+        sessionId={sessionId}
+      />
+    </div>
+  );
+}

