+              </p>
+              <button
+                type="button"
+                onClick={handleCopy}
+                className="rounded border border-purple-700 bg-purple-950/60 px-2 py-0.5 text-[8px] font-bold uppercase tracking-widest text-purple-300 transition-colors hover:bg-purple-900/40"
+              >
