+
+const NOW = "2026-06-12T10:00:00.000Z";
+
+function makeEntry(overrides: Partial<ScribeEntry> = {}): ScribeEntry {
+  return createScribeEntry({
+    createdAt: NOW,
+    source: "claude",
+    actor: "claude",
+    project: "JARVIS",
+    type: "RESULT",
+    title: "Built the scribe system",
