+/**
+ * Jarvis Memory Protocol — types.
+ *
+ * What Jarvis is allowed to remember, how candidates are classified, and the
+ * honest backing status of the store. Pure type definitions only.
+ */
+
+export type MemoryType =
+  | "OWNER_PREFERENCE"
+  | "PROJECT_FACT"
+  | "SYSTEM_STATE"
+  | "DECISION"
+  | "PROMPT_PATTERN"
